#!/usr/bin/env python3
"""XZ Utils 5.8.2 reimplementation"""
import sys, os, io, struct, stat, shutil, lzma, errno, time
from pathlib import Path

PROGRAM_NAME = os.path.basename(sys.argv[0])
XZ_VERSION = "5.8.2"
LIBLZMA_VERSION = "5.8.2"
XZ_VERSION_NUM = 50080022
LIBLZMA_VERSION_NUM = 50080022

CHECK_NONE=0; CHECK_CRC32=1; CHECK_CRC64=4; CHECK_SHA256=10
CHECK_NAMES={0:'None',1:'CRC32',4:'CRC64',10:'SHA-256'}
CHECK_SIZES={0:0,1:4,4:8,10:32}
LZMA_CHECK={0:lzma.CHECK_NONE,1:lzma.CHECK_CRC32,4:lzma.CHECK_CRC64,10:lzma.CHECK_SHA256}

# Preset params: (dict_bytes, mode_str, mf_str, nice, depth, lc, lp, pb)
PRESETS = {
    1:(1<<20,'fast','hc4',128,8,3,0,2),
    2:(2<<20,'fast','hc4',273,24,3,0,2),
    3:(4<<20,'fast','hc4',273,48,3,0,2),
    4:(4<<20,'normal','bt4',16,0,3,0,2),
    5:(8<<20,'normal','bt4',32,0,3,0,2),
    6:(8<<20,'normal','bt4',64,0,3,0,2),
    7:(16<<20,'normal','bt4',64,0,3,0,2),
    8:(32<<20,'normal','bt4',64,0,3,0,2),
    9:(64<<20,'normal','bt4',64,0,3,0,2),
}
EXTREME_PRESETS = {
    1:(1<<20,'normal','bt4',273,512,3,0,2),
    2:(2<<20,'normal','bt4',273,512,3,0,2),
    3:(4<<20,'normal','bt4',273,512,3,0,2),
    4:(4<<20,'normal','bt4',273,512,3,0,2),
    5:(8<<20,'normal','bt4',273,512,3,0,2),
    6:(8<<20,'normal','bt4',273,512,3,0,2),
    7:(16<<20,'normal','bt4',273,512,3,0,2),
    8:(32<<20,'normal','bt4',273,512,3,0,2),
    9:(64<<20,'normal','bt4',273,512,3,0,2),
}
# T1 memory MiB
PRESET_MEM_T1={1:9,2:17,3:32,4:48,5:94,6:94,7:186,8:370,9:674}
EXTREME_MEM_T1={1:13,2:25,3:48,4:48,5:94,6:94,7:186,8:370,9:674}
# Decomp memory MiB (dict+1)
PRESET_DECOMP={1:2,2:3,3:5,4:5,5:9,6:9,7:17,8:33,9:65}

def format_size(n):
    if n < 10000: return '%d B' % n
    v = n/1024.0
    if v < 10000: return '%.1f KiB' % v
    v /= 1024.0
    if v < 10000: return '%.1f MiB' % v
    v /= 1024.0
    if v < 10000: return '%.1f GiB' % v
    return '%.1f TiB' % (v/1024.0)

def format_size_verbose(n):
    if n < 10000: return '%d B' % n
    return '%s (%d B)' % (format_size(n), n)

def format_ratio(c, u):
    if u == 0: return '---'
    r = c/u
    if r >= 9.9995: return '---'
    return '%.3f' % r

def read_vli(data, pos):
    r,s = 0,0
    while pos < len(data):
        b = data[pos]; pos += 1
        r |= (b&0x7f) << s
        if not (b&0x80): return r, pos
        s += 7
        if s >= 63: raise ValueError("VLI too large")
    raise ValueError("Truncated VLI")

def parse_xz_data(data):
    pos = 0; streams = []
    if not data: return None, "File format not recognized"
    while pos < len(data):
        if len(data)-pos < 12: break
        if data[pos:pos+6] != b'\xfd7zXZ\x00':
            if not streams: return None, "File format not recognized"
            break
        sstart = pos
        sf = data[pos+6:pos+8]
        if sf[0] != 0 or sf[1]&0xf0: return None, "Unsupported options"
        ct = sf[1] & 0x0f
        pos += 12
        blocks=[]; uoff=0
        while True:
            if pos >= len(data): return None, "Unexpected end of file"
            if data[pos] == 0x00:
                istart=pos; pos+=1
                try:
                    nr,pos = read_vli(data,pos)
                    recs=[]
                    for _ in range(nr):
                        up,pos = read_vli(data,pos); uc,pos = read_vli(data,pos)
                        recs.append((up,uc))
                except: return None, "Compressed data is corrupt"
                while (pos-istart)%4!=0: pos+=1
                if pos+4>len(data): return None, "Unexpected end of file"
                pos+=4; break
            bstart=pos; bco=pos-sstart
            bsf=data[pos]; bhs=(bsf+1)*4
            if pos+bhs>len(data): return None, "Unexpected end of file"
            bf=data[pos+1]; nf=(bf&3)+1
            hcs=bool(bf&0x40); hus=bool(bf&0x80)
            hp=pos+2; cs=None; us=None
            try:
                if hcs: cs,hp=read_vli(data,hp)
                if hus: us,hp=read_vli(data,hp)
                for _ in range(nf):
                    fi,hp=read_vli(data,hp); fs,hp=read_vli(data,hp); hp+=fs
            except: return None, "Compressed data is corrupt"
            cksz=CHECK_SIZES.get(ct,0)
            if cs is None: return None, "Block header missing compressed size"
            up_sz=bhs+cs+cksz
            te=bstart+bhs+cs+cksz
            if te%4!=0: te+=4-(te%4)
            bts=te-bstart; pos=bstart+bts
            if us is None: us=0
            blocks.append({'co':bco,'uo':uoff,'ts':bts,'us':us,'ct':ct,'up':up_sz})
            uoff+=us
        if pos+12>len(data): return None, "Unexpected end of file"
        ft=data[pos:pos+12]
        if ft[10:12]!=b'YZ': return None, "Compressed data is corrupt"
        send=pos+12; pos=send
        pad=0
        ps=pos
        while pos<len(data) and data[pos]==0: pos+=1
        pad=pos-ps
        streams.append({'start':sstart,'end':send,'blocks':blocks,'ct':ct,
                       'pad':pad,'cs':send-sstart,'us':uoff})
    if not streams: return None, "File format not recognized"
    return streams, None

class XzOptions:
    def __init__(self):
        self.mode = None  # 'compress','decompress','test','list'
        self.keep = False
        self.force = False
        self.stdout = False
        self.no_sync = False
        self.single_stream = False
        self.no_sparse = False
        self.suffix = None
        self.files_from = None
        self.files_null = False
        self.format = 'auto'  # auto,xz,lzma,lzip,raw
        self.check = CHECK_CRC64
        self.ignore_check = False
        self.preset = 6
        self.extreme = False
        self.threads = 0
        self.block_size = None
        self.block_list = None
        self.flush_timeout = None
        self.memlimit_compress = None
        self.memlimit_decompress = None
        self.memlimit_mt_decompress = None
        self.no_adjust = False
        self.quiet = 0  # 0,1,2
        self.verbose = 0  # 0,1,2
        self.no_warn = False
        self.robot = False
        self.info_memory = False
        self.lzma_opts = None  # custom lzma1/2 opts
        self.filters = None
        self.filenames = []
        self.exit_status = 0  # 0=ok,1=error,2=warning

opts = XzOptions()
warn_count = 0

def msg_error(fmt, *args):
    if opts.quiet < 2:
        sys.stderr.write('%s: %s\n' % (PROGRAM_NAME, fmt % args if args else fmt))
    if opts.exit_status < 1: opts.exit_status = 1

def msg_warn(fmt, *args):
    global warn_count
    warn_count += 1
    if opts.quiet < 1:
        sys.stderr.write('%s: %s\n' % (PROGRAM_NAME, fmt % args if args else fmt))
    if not opts.no_warn and opts.exit_status < 2: opts.exit_status = 2

def msg_verbose(fmt, *args):
    if opts.verbose >= 1:
        sys.stderr.write('%s: %s\n' % (PROGRAM_NAME, fmt % args if args else fmt))

def msg_verbose2(fmt, *args):
    if opts.verbose >= 2:
        sys.stderr.write('%s: %s\n' % (PROGRAM_NAME, fmt % args if args else fmt))

def get_suffix():
    if opts.suffix: return opts.suffix
    if opts.format == 'lzma': return '.lzma'
    return '.xz'

def compressed_suffix(fname):
    """Get the compressed filename"""
    return fname + get_suffix()

def decompressed_name(fname):
    """Get decompressed filename by removing suffix"""
    suf = get_suffix()
    if fname.endswith(suf): return fname[:-len(suf)]
    # Also handle standard suffixes
    for s in ['.xz', '.lzma', '.lz', '.lzo', '.gz', '.bz2', '.z', '.Z']:
        if fname.endswith(s): return fname[:-len(s)]
    return None

def get_lzma_format():
    f = opts.format
    if f == 'auto': return lzma.FORMAT_AUTO
    if f == 'xz': return lzma.FORMAT_XZ
    if f == 'lzma': return lzma.FORMAT_ALONE
    if f == 'raw': return lzma.FORMAT_RAW
    return lzma.FORMAT_AUTO

def get_preset_lzma_preset():
    p = opts.preset
    if opts.extreme:
        return p | lzma.PRESET_EXTREME
    return p

def get_lzma_check():
    return LZMA_CHECK.get(opts.check, lzma.CHECK_CRC64)

def compress_data(data):
    fmt = get_lzma_format()
    if fmt == lzma.FORMAT_RAW:
        filters = opts.filters if opts.filters else [{"id": lzma.FILTER_LZMA2, "preset": get_preset_lzma_preset()}]
        if opts.verbose == 0 or True:
            pass
        try:
            return lzma.compress(data, format=fmt, filters=filters)
        except Exception as e:
            raise
    else:
        try:
            return lzma.compress(data, format=fmt, check=get_lzma_check(),
                               preset=get_preset_lzma_preset())
        except Exception as e:
            raise

def decompress_data(data, single_stream=False):
    fmt = get_lzma_format()
    if single_stream and fmt in (lzma.FORMAT_AUTO, lzma.FORMAT_XZ):
        # Decompress only first stream
        dec = lzma.LZMADecompressor(format=fmt)
        result = dec.decompress(data)
        return result
    try:
        if opts.ignore_check:
            # Try to decompress ignoring check errors
            dec = lzma.LZMADecompressor(format=fmt)
            try:
                result = dec.decompress(data)
                return result
            except lzma.LZMAError:
                # Try with memlimit workaround - decompress what we can
                dec2 = lzma.LZMADecompressor(format=fmt)
                buf = b''
                pos = 0
                chunk = 65536
                while pos < len(data):
                    try:
                        buf += dec2.decompress(data[pos:pos+chunk])
                        pos += chunk
                        if dec2.eof: break
                    except lzma.LZMAError:
                        break
                return buf
        return lzma.decompress(data, format=fmt)
    except lzma.LZMAError:
        raise

def get_ram_mib():
    try:
        with open('/proc/meminfo') as f:
            for line in f:
                if line.startswith('MemTotal:'):
                    kb = int(line.split()[1])
                    return kb // 1024
    except:
        pass
    return 8192

def get_mt_decomp_limit_mib():
    ram = get_ram_mib()
    return int(ram * 0.25)

def get_comp_mem_mib(nthreads):
    p = opts.preset
    extreme = opts.extreme
    if nthreads <= 1:
        if extreme:
            return EXTREME_MEM_T1.get(p, 94)
        return PRESET_MEM_T1.get(p, 94)
    # MT memory estimation
    t1_mem = EXTREME_MEM_T1.get(p, 94) if extreme else PRESET_MEM_T1.get(p, 94)
    # Get dict size
    params = EXTREME_PRESETS.get(p, PRESETS.get(p)) if extreme else PRESETS.get(p)
    if params:
        dict_mib = params[0] / (1024*1024)
    else:
        dict_mib = 8
    # per_thread_MT = t1_mem + dict_mib * 9 - 0.896
    extra = dict_mib * 9 - 0.896
    per_thread = t1_mem + extra
    return int(round(nthreads * per_thread))

def get_decomp_mem_mib():
    return PRESET_DECOMP.get(opts.preset, 9)

def get_filter_chain_str():
    p = opts.preset
    extreme = opts.extreme
    params = EXTREME_PRESETS.get(p, PRESETS.get(p)) if extreme else PRESETS.get(p)
    if params is None:
        params = PRESETS[6]
    d, mode, mf, nice, depth, lc, lp, pb = params
    d_str = '%dMiB' % (d>>20) if d >= (1<<20) else '%dKiB' % (d>>10)
    return '--lzma2=dict=%s,lc=%d,lp=%d,pb=%d,mode=%s,nice=%d,mf=%s,depth=%d' % (
        d_str, lc, lp, pb, mode, nice, mf, depth)

def show_verbose_info(filename, comp_size, uncomp_size, is_compress):
    if opts.verbose < 1: return
    if uncomp_size == 0:
        ratio_str = '---'
        sym = '>'
    else:
        r = comp_size / uncomp_size
        if r >= 9.9995:
            ratio_str = '9.999'
            sym = '>'
        else:
            ratio_str = '%.3f' % r
            sym = '='
    comp_str = format_size(comp_size)
    uncomp_str = format_size(uncomp_size)
    sys.stderr.write('%s: %s / %s %s %s\n' % (filename, comp_str, uncomp_str, sym, ratio_str))

def show_vv_info(nthreads):
    if opts.verbose < 2: return
    msg_verbose2(get_filter_chain_str())
    mt_limit = get_mt_decomp_limit_mib()
    if nthreads != 1:
        msg_verbose2('Using up to %d threads.', nthreads)
    comp_mem = get_comp_mem_mib(nthreads)
    if opts.memlimit_compress:
        limit_mib = opts.memlimit_compress // (1024*1024)
        msg_verbose2('%d MiB of memory is required. The limit is %d MiB.', comp_mem, limit_mib)
    else:
        msg_verbose2('%d MiB of memory is required. The limiter is disabled.', comp_mem)
    decomp_mem = get_decomp_mem_mib()
    msg_verbose2('Decompression will need %d MiB of memory.', decomp_mem)
    # Check if thread reduction needed
    if nthreads > 1 and opts.memlimit_compress is None:
        per_thread = comp_mem / nthreads
        limit = mt_limit
        max_t = int(limit / per_thread)
        if max_t < nthreads and max_t > 0:
            msg_verbose2('Reduced the number of threads from %d to %d to not exceed the memory usage limit of %d MiB',
                        nthreads, max_t, limit)

def do_info_memory():
    ram_b = get_ram_mib() * 1024 * 1024
    ram_mib = get_ram_mib()
    mt_limit_b = get_mt_decomp_limit_mib() * 1024 * 1024
    mt_limit_mib = get_mt_decomp_limit_mib()
    ncpu = os.cpu_count() or 1
    if opts.robot:
        print('%d\t0\t0\t%d\t%d\t%d' % (ram_b, mt_limit_b, mt_limit_b, ncpu))
    else:
        print('Hardware information:')
        print('  Amount of physical memory (RAM):  %d MiB (%d B)' % (ram_mib, ram_b))
        print('  Number of processor threads:      %d' % ncpu)
        print()
        print('Memory usage limits:')
        print('  Compression:                      Disabled')
        print('  Decompression:                    Disabled')
        print('  Multi-threaded decompression:     %d MiB (%d B)' % (mt_limit_mib, mt_limit_b))
        print('  Default for -T0:                  %d MiB (%d B)' % (mt_limit_mib, mt_limit_b))

def process_compress_stdin():
    data = sys.stdin.buffer.read()
    if opts.verbose >= 2:
        ncpu = os.cpu_count() or 1
        nthreads = opts.threads if opts.threads != 0 else ncpu
        show_vv_info(nthreads)
    try:
        comp = compress_data(data)
    except Exception as e:
        msg_error('(stdin): %s', str(e))
        return False
    sys.stdout.buffer.write(comp)
    if opts.verbose >= 1:
        show_verbose_info('(stdin)', len(comp), len(data), True)
    return True

def process_decompress_stdin():
    data = sys.stdin.buffer.read()
    try:
        decomp = decompress_data(data, opts.single_stream)
    except lzma.LZMAError as e:
        err = str(e)
        if 'check' in err.lower() or 'crc' in err.lower():
            msg_error('(stdin): Compressed data is corrupt')
        else:
            msg_error('(stdin): File format not recognized')
        return False
    except Exception as e:
        msg_error('(stdin): %s', str(e))
        return False
    sys.stdout.buffer.write(decomp)
    if opts.verbose >= 1:
        show_verbose_info('(stdin)', len(data), len(decomp), False)
    return True

