def list_files(filenames):
    if not filenames:
        msg_error('--list does not support reading from standard input')
        return False
    # Check for stdin
    if '-' in filenames or not filenames:
        msg_error('--list does not support reading from standard input')
        return False
    all_ok = True
    total_streams=0; total_blocks=0; total_comp=0; total_uncomp=0
    total_padding=0; total_files=0; all_checks=set()
    file_infos = []
    for fname in filenames:
        streams, err = parse_xz_file_wrap(fname)
        if err:
            msg_error('%s: %s', fname, err)
            all_ok = False
            continue
        fs=sum(1 for s in streams)
        fb=sum(len(s['blocks']) for s in streams)
        fc=sum(s['cs'] for s in streams)
        fu=sum(s['us'] for s in streams)
        fp=sum(s['pad'] for s in streams)
        fcts=set(s['ct'] for s in streams)
        file_infos.append((fname, streams, fs, fb, fc, fu, fp, fcts))
        total_streams+=fs; total_blocks+=fb; total_comp+=fc
        total_uncomp+=fu; total_padding+=fp; total_files+=1
        all_checks |= fcts
    nfiles = len(file_infos)
    if not opts.verbose and not opts.robot:
        # Short format
        print('Strms  Blocks   Compressed Uncompressed  Ratio  Check   Filename')
        for fname, streams, fs, fb, fc, fu, fp, fcts in file_infos:
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            print('%5d  %6d   %10s %12s  %5s  %-8s%s' % (
                fs, fb, format_size(fc), format_size(fu), format_ratio(fc,fu), ct_str, fname))
        if nfiles > 1:
            print('-'*79)
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(all_checks))
            print('%5d  %6d   %10s %12s  %5s  %-8s%d files' % (
                total_streams, total_blocks, format_size(total_comp), format_size(total_uncomp),
                format_ratio(total_comp, total_uncomp), ct_str, nfiles))
    elif opts.robot:
        for fname, streams, fs, fb, fc, fu, fp, fcts in file_infos:
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            print('name\t%s' % fname)
            print('file\t%d\t%d\t%d\t%d\t%s\t%s\t%d' % (fs,fb,fc,fu,format_ratio(fc,fu),ct_str,fp))
            if opts.verbose >= 1:
                gblock = 0
                for si, s in enumerate(streams, 1):
                    sco = s['start'] - (streams[0]['start'] if streams else 0)  # relative to file start
                    # Actually offset from file start:
                    sco2 = s['start']
                    suo = sum(streams[j]['us'] for j in range(si-1))
                    sct = CHECK_NAMES.get(s['ct'],'?')
                    print('stream\t%d\t%d\t%d\t%d\t%d\t%d\t%s\t%s\t%d' % (
                        si, len(s['blocks']), sco2, suo, s['cs'], s['us'],
                        format_ratio(s['cs'],s['us']), sct, s['pad']))
                    for bi, b in enumerate(s['blocks'], 1):
                        gblock += 1
                        bct = CHECK_NAMES.get(b['ct'],'?')
                        bco = b['co'] + s['start']  # absolute offset
                        print('block\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%s\t%s' % (
                            si, bi, gblock, bco, b['uo']+suo, b['ts'], b['us'],
                            format_ratio(b['ts'],b['us']), bct))
        ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(all_checks))
        print('totals\t%d\t%d\t%d\t%d\t%s\t%s\t%d\t%d' % (
            total_streams, total_blocks, total_comp, total_uncomp,
            format_ratio(total_comp,total_uncomp), ct_str, total_padding, nfiles))
    else:
        # Verbose non-robot format
        for fi, (fname, streams, fs, fb, fc, fu, fp, fcts) in enumerate(file_infos, 1):
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            if opts.verbose >= 1:
                print('%s (%d/%d)' % (fname, fi, nfiles))
                print('  %-19s%d' % ('Streams:', fs))
                print('  %-19s%d' % ('Blocks:', fb))
                print('  %-19s%s' % ('Compressed size:', format_size_verbose(fc)))
                print('  %-19s%s' % ('Uncompressed size:', format_size_verbose(fu)))
                print('  %-19s%s' % ('Ratio:', format_ratio(fc,fu)))
                print('  %-19s%s' % ('Check:', ct_str))
                print('  %-19s%s' % ('Stream Padding:', format_size_verbose(fp)))
                # Streams table
                print('  Streams:')
                print('    Stream    Blocks      CompOffset    UncompOffset        CompSize      UncompSize  Ratio  Check      Padding')
                uoff = 0
                for si, s in enumerate(streams, 1):
                    sct = CHECK_NAMES.get(s['ct'],'?')
                    print('%10d%10d%16d%16d%16d%16d%7s  %-11s%7d' % (
                        si, len(s['blocks']), s['start'], uoff,
                        s['cs'], s['us'], format_ratio(s['cs'],s['us']), sct, s['pad']))
                    uoff += s['us']
                # Blocks table
                print('  Blocks:')
                print('    Stream     Block      CompOffset    UncompOffset       TotalSize      UncompSize  Ratio  Check')
                for si, s in enumerate(streams, 1):
                    suo = sum(streams[j]['us'] for j in range(si-1))
                    for bi, b in enumerate(s['blocks'], 1):
                        bct = CHECK_NAMES.get(b['ct'],'?')
                        bco = b['co'] + s['start']
                        print('%10d%10d%16d%16d%16d%16d%7s  %s' % (
                            si, bi, bco, b['uo']+suo, b['ts'], b['us'],
                            format_ratio(b['ts'],b['us']), bct))
                print()
        if nfiles > 1:
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(all_checks))
            print('Totals:')
            print('  %-19s%d' % ('Number of files:', nfiles))
            print('  %-19s%d' % ('Streams:', total_streams))
            print('  %-19s%d' % ('Blocks:', total_blocks))
            print('  %-19s%s' % ('Compressed size:', format_size_verbose(total_comp)))
            print('  %-19s%s' % ('Uncompressed size:', format_size_verbose(total_uncomp)))
            print('  %-19s%s' % ('Ratio:', format_ratio(total_comp, total_uncomp)))
            print('  %-19s%s' % ('Check:', ct_str))
            print('  %-19s%s' % ('Stream Padding:', format_size_verbose(total_padding)))
    return all_ok

def parse_xz_file_wrap(fname):
    try:
        with open(fname, 'rb') as f:
            data = f.read()
        streams, err = parse_xz_data(data)
        if err:
            return None, err
        # Fix stream start offsets to be absolute within file
        offset = 0
        for s in streams:
            s['start'] = offset
            for b in s['blocks']:
                pass  # b['co'] already relative to stream start
            offset += s['cs'] + s['pad']
        return streams, None
    except OSError as e:
        return None, e.strerror

def parse_size(s):
    """Parse size string like '100M', '1GiB', '50%'"""
    s = s.strip()
    if s.endswith('%'):
        ram = get_ram_mib() * 1024 * 1024
        return int(ram * float(s[:-1]) / 100)
    mult = 1
    num = s
    if s[-1].lower() in 'kmgtpe' or s.upper().endswith(('KIB','MIB','GIB','TIB','KB','MB','GB','TB')):
        for suffix, val in [('TiB',1<<40),('GiB',1<<30),('MiB',1<<20),('KiB',1<<10),
                             ('TB',10**12),('GB',10**9),('MB',10**6),('KB',10**3),
                             ('T',1<<40),('G',1<<30),('M',1<<20),('K',1<<10)]:
            if s.upper().endswith(suffix.upper()):
                num = s[:-len(suffix)]
                mult = val
                break
    return int(float(num) * mult)

def parse_args():
    global opts
    i = 1
    args = sys.argv[1:]
    n = len(args)

    # Detect command mode from program name
    prog = PROGRAM_NAME
    if prog in ('unxz',): opts.mode = 'decompress'
    elif prog in ('xzcat',): opts.mode = 'decompress'; opts.stdout = True
    elif prog in ('lzma',): opts.format = 'lzma'
    elif prog in ('unlzma',): opts.mode = 'decompress'; opts.format = 'lzma'
    elif prog in ('lzcat',): opts.mode = 'decompress'; opts.stdout = True; opts.format = 'lzma'

    i = 0
    while i < len(args):
        a = args[i]
        if a == '--':
            i += 1
            break
        if not a.startswith('-'):
            opts.filenames.append(a)
            i += 1
            continue
        if a.startswith('--'):
            # Long options
            if a == '--compress' or a == '--compress': opts.mode = 'compress'
            elif a == '--decompress' or a == '--uncompress': opts.mode = 'decompress'
            elif a == '--test': opts.mode = 'test'
            elif a == '--list': opts.mode = 'list'
            elif a == '--keep': opts.keep = True
            elif a == '--force': opts.force = True
            elif a == '--stdout' or a == '--to-stdout': opts.stdout = True
            elif a == '--no-sync': opts.no_sync = True
            elif a == '--single-stream': opts.single_stream = True
            elif a == '--no-sparse': opts.no_sparse = True
            elif a.startswith('--suffix='):
                opts.suffix = a[9:]
                if not opts.suffix.startswith('.'):
                    opts.suffix = '.' + opts.suffix
            elif a == '--suffix':
                i += 1
                opts.suffix = args[i]
                if not opts.suffix.startswith('.'):
                    opts.suffix = '.' + opts.suffix
            elif a.startswith('--files='):
                opts.files_from = a[8:]
            elif a == '--files':
                opts.files_from = '-'
            elif a.startswith('--files0='):
                opts.files_from = a[9:]; opts.files_null = True
            elif a == '--files0':
                opts.files_from = '-'; opts.files_null = True
            elif a.startswith('--format='):
                opts.format = a[9:].lower()
                if opts.format not in ('auto','xz','lzma','lzip','raw'):
                    msg_error('%s: Unknown file format type', a[9:])
                    sys.exit(1)
            elif a == '--format':
                i += 1
                opts.format = args[i].lower()
                if opts.format not in ('auto','xz','lzma','lzip','raw'):
                    msg_error('%s: Unknown file format type', args[i])
                    sys.exit(1)
            elif a.startswith('--check='):
                cs = a[8:].lower()
                check_map = {'none':CHECK_NONE,'crc32':CHECK_CRC32,'crc64':CHECK_CRC64,'sha256':CHECK_SHA256}
                if cs not in check_map:
                    msg_error('%s: Unknown integrity check type', a[8:])
                    sys.exit(1)
                opts.check = check_map[cs]
            elif a == '--check':
                i += 1
                cs = args[i].lower()
                check_map = {'none':CHECK_NONE,'crc32':CHECK_CRC32,'crc64':CHECK_CRC64,'sha256':CHECK_SHA256}
                if cs not in check_map:
                    msg_error('%s: Unknown integrity check type', args[i])
                    sys.exit(1)
                opts.check = check_map[cs]
            elif a == '--ignore-check': opts.ignore_check = True
            elif a == '--extreme': opts.extreme = True
            elif a.startswith('--threads='):
                opts.threads = int(a[10:])
            elif a == '--threads' or a == '-T':
                i += 1; opts.threads = int(args[i])
            elif a.startswith('--block-size='):
                opts.block_size = parse_size(a[13:])
            elif a.startswith('--memlimit-compress='):
                opts.memlimit_compress = parse_size(a[20:])
            elif a.startswith('--memlimit-decompress='):
                opts.memlimit_decompress = parse_size(a[22:])
            elif a.startswith('--memlimit-mt-decompress='):
                opts.memlimit_mt_decompress = parse_size(a[25:])
            elif a.startswith('--memlimit=') or a.startswith('-M='):
                v = parse_size(a.split('=',1)[1])
                opts.memlimit_compress = v; opts.memlimit_decompress = v
                opts.memlimit_mt_decompress = v
            elif a == '--no-adjust': opts.no_adjust = True
            elif a == '--quiet': opts.quiet += 1
            elif a == '--verbose': opts.verbose += 1
            elif a == '--no-warn': opts.no_warn = True
            elif a == '--robot': opts.robot = True
            elif a == '--info-memory': opts.info_memory = True
            elif a == '--help' or a == '-h':
                show_help(False); sys.exit(0)
            elif a == '--long-help' or a == '-H':
                show_help(True); sys.exit(0)
            elif a == '--version' or a == '-V':
                show_version(); sys.exit(0)
            elif a.startswith('--lzma1') or a.startswith('--lzma2'):
                pass  # Accept but use preset
            elif a.startswith('--x86') or a.startswith('--arm') or a.startswith('--powerpc') \
                 or a.startswith('--ia64') or a.startswith('--sparc') or a.startswith('--riscv') \
                 or a.startswith('--delta'):
                pass  # Accept filter options
            elif a.startswith('--filters'):
                pass  # Accept
            elif a.startswith('--block-list=') or a.startswith('--flush-timeout='):
                pass  # Accept
            else:
                msg_error('%s: Unknown option', a)
                sys.exit(1)
        else:
            # Short options
            j = 1
            while j < len(a):
                c = a[j]
                if c == 'z': opts.mode = 'compress'
                elif c == 'd': opts.mode = 'decompress'
                elif c == 't': opts.mode = 'test'
                elif c == 'l': opts.mode = 'list'
                elif c == 'k': opts.keep = True
                elif c == 'f': opts.force = True
                elif c == 'c': opts.stdout = True
                elif c == 'e': opts.extreme = True
                elif c == 'q': opts.quiet += 1
                elif c == 'v': opts.verbose += 1
                elif c == 'Q': opts.no_warn = True
                elif c in '0123456789': opts.preset = int(c)
