    parse_args()

    if opts.info_memory:
        do_info_memory()
        sys.exit(0)

    # Handle version flag
    # (already handled in parse_args)

    # Handle --format=lzip compress
    if opts.format == 'lzip' and opts.mode != 'decompress' and opts.mode != 'test':
        msg_error('Compression of lzip files (.lz) is not supported')
        sys.exit(1)

    # Handle --no-adjust with memlimit
    if opts.no_adjust and opts.memlimit_compress:
        p = opts.preset
        limit_mib = opts.memlimit_compress // (1024*1024)
        ncpu = os.cpu_count() or 1
        nthreads = opts.threads if opts.threads != 0 else ncpu
        comp_mem = get_comp_mem_mib(nthreads)
        if comp_mem > limit_mib:
            msg_error('Memory usage limit is too low for the given filter setup.')
            msg_error('%d MiB of memory is required. The limit is %d MiB.', comp_mem, limit_mib)
