    mode = opts.mode
    if mode is None:
        # Determine from context
        prog = PROGRAM_NAME
        if prog in ('unxz', 'unlzma'):
            mode = 'decompress'
        elif prog in ('xzcat', 'lzcat'):
            mode = 'decompress'
            opts.stdout = True
        else:
            mode = 'compress'

    if mode == 'list':
        if not opts.filenames:
            msg_error('--list does not support reading from standard input')
            sys.exit(1)
        ok = list_files(opts.filenames)
        sys.exit(opts.exit_status)

    # Get filenames
    filenames = opts.filenames if opts.filenames else ['-']

    for fname in filenames:
        if mode == 'compress':
            process_file_compress(fname)
        elif mode == 'decompress':
            process_file_decompress(fname)
        elif mode == 'test':
            process_file_test(fname)

    sys.exit(opts.exit_status)

