def format_size(n):
    if n < 10000: return '%d B' % n
    v = n/1024.0
    if v < 10000: return '%.1f KiB' % v
    v /= 1024.0
    if v < 10000: return '%.1f MiB' % v
    v /= 1024.0
    if v < 10000: return '%.1f GiB' % v
    return '%.1f TiB' % (v/1024.0)

def format_size_verbose(n):
    if n < 10000: return '%d B' % n
    return '%s (%d B)' % (format_size(n), n)

def format_ratio(c, u):
    if u == 0: return '---'
    r = c/u
    if r >= 9.9995: return '---'
    return '%.3f' % r

def read_vli(data, pos):
    r,s = 0,0
    while pos < len(data):
        b = data[pos]; pos += 1
        r |= (b&0x7f) << s
        if not (b&0x80): return r, pos
        s += 7
        if s >= 63: raise ValueError("VLI too large")
    raise ValueError("Truncated VLI")

def parse_xz_data(data):
    pos = 0; streams = []
    if not data: return None, "File format not recognized"
    while pos < len(data):
        if len(data)-pos < 12: break
        if data[pos:pos+6] != b'\xfd7zXZ\x00':
            if not streams: return None, "File format not recognized"
            break
        sstart = pos
        sf = data[pos+6:pos+8]
        if sf[0] != 0 or sf[1]&0xf0: return None, "Unsupported options"
        ct = sf[1] & 0x0f
        pos += 12
        blocks=[]; uoff=0
        while True:
            if pos >= len(data): return None, "Unexpected end of file"
            if data[pos] == 0x00:
                istart=pos; pos+=1
                try:
                    nr,pos = read_vli(data,pos)
                    recs=[]
                    for _ in range(nr):
                        up,pos = read_vli(data,pos); uc,pos = read_vli(data,pos)
                        recs.append((up,uc))
                except: return None, "Compressed data is corrupt"
                while (pos-istart)%4!=0: pos+=1
                if pos+4>len(data): return None, "Unexpected end of file"
                pos+=4; break
            bstart=pos; bco=pos-sstart
            bsf=data[pos]; bhs=(bsf+1)*4
            if pos+bhs>len(data): return None, "Unexpected end of file"
            bf=data[pos+1]; nf=(bf&3)+1
            hcs=bool(bf&0x40); hus=bool(bf&0x80)
            hp=pos+2; cs=None; us=None
            try:
                if hcs: cs,hp=read_vli(data,hp)
                if hus: us,hp=read_vli(data,hp)
                for _ in range(nf):
                    fi,hp=read_vli(data,hp); fs,hp=read_vli(data,hp); hp+=fs
            except: return None, "Compressed data is corrupt"
            cksz=CHECK_SIZES.get(ct,0)
            if cs is None: return None, "Block header missing compressed size"
            up_sz=bhs+cs+cksz
            te=bstart+bhs+cs+cksz
            if te%4!=0: te+=4-(te%4)
            bts=te-bstart; pos=bstart+bts
            if us is None: us=0
            blocks.append({'co':bco,'uo':uoff,'ts':bts,'us':us,'ct':ct,'up':up_sz})
            uoff+=us
        if pos+12>len(data): return None, "Unexpected end of file"
        ft=data[pos:pos+12]
        if ft[10:12]!=b'YZ': return None, "Compressed data is corrupt"
        send=pos+12; pos=send
        pad=0
        ps=pos
        while pos<len(data) and data[pos]==0: pos+=1
        pad=pos-ps
        streams.append({'start':sstart,'end':send,'blocks':blocks,'ct':ct,
