def is_tty(f):
    try: return os.isatty(f.fileno())
    except: return False

def process_file_compress(fname):
    if fname == '-':
        if is_tty(sys.stdout) and not opts.force:
            msg_error('Compressed data not written to a terminal')
            msg_error("Use '--force' to ignore this, '--stdout' to write to stdout, or")
            msg_error("'--help' for more information.")
            return False
        return process_compress_stdin()
    # Check if file exists
    try:
        st = os.stat(fname)
    except OSError as e:
        msg_error('%s: %s', fname, e.strerror)
        return False
    # Check if it's a regular file
    if not stat.S_ISREG(st.st_mode) and not stat.S_ISLNK(st.st_mode):
        if not opts.force:
            msg_warn('%s: Not a regular file, skipping', fname)
            return False
    # Check suffix - refuse to compress already-compressed files
    suf = get_suffix()
    if not opts.force and fname.endswith(suf):
        msg_warn("%s: File already has '%s' suffix, skipping", fname, suf)
        return False
    # Determine output filename
    if opts.stdout:
        outfname = None
    else:
        outfname = compressed_suffix(fname)
        # Check if output exists
        if not opts.force and os.path.exists(outfname):
            msg_error('%s: File exists', outfname)
            return False
    # Read input
    try:
        with open(fname, 'rb') as f:
            data = f.read()
    except OSError as e:
        msg_error('%s: %s', fname, e.strerror)
        return False
    if opts.verbose >= 2:
        ncpu = os.cpu_count() or 1
        nthreads = opts.threads if opts.threads != 0 else ncpu
        show_vv_info(nthreads)
    # Compress
    try:
        comp = compress_data(data)
    except Exception as e:
        msg_error('%s: %s', fname, str(e))
        return False
    # Write output
    if opts.stdout or outfname is None:
        sys.stdout.buffer.write(comp)
    else:
        try:
            with open(outfname, 'wb') as f:
                f.write(comp)
            # Copy permissions
            try:
                os.chmod(outfname, stat.S_IMODE(st.st_mode))
            except: pass
            # Copy timestamps
            try:
                os.utime(outfname, (st.st_atime, st.st_mtime))
            except: pass
        except OSError as e:
            msg_error('%s: %s', outfname, e.strerror)
            try: os.unlink(outfname)
            except: pass
            return False
        if not opts.keep:
            try: os.unlink(fname)
            except: pass
    if opts.verbose >= 1:
        show_verbose_info(fname, len(comp), len(data), True)
    return True

def process_file_decompress(fname):
    if fname == '-':
        return process_decompress_stdin()
    try:
        st = os.stat(fname)
    except OSError as e:
        msg_error('%s: %s', fname, e.strerror)
        return False
    # Determine output filename
    if opts.stdout:
        outfname = None
    else:
        outfname = decompressed_name(fname)
        if outfname is None:
            msg_warn('%s: Unknown suffix, skipping', fname)
            return False
        if not opts.force and os.path.exists(outfname):
            msg_error('%s: File exists', outfname)
            return False
    # Read input
    try:
        with open(fname, 'rb') as f:
            data = f.read()
    except OSError as e:
        msg_error('%s: %s', fname, e.strerror)
        return False
    # Decompress
    try:
        decomp = decompress_data(data, opts.single_stream)
    except lzma.LZMAError as e:
        err = str(e).lower()
        if 'check' in err or 'crc' in err or 'integrity' in err:
            msg_error('%s: Compressed data is corrupt', fname)
        else:
            msg_error('%s: File format not recognized', fname)
        return False
    except Exception as e:
        msg_error('%s: File format not recognized', fname)
        return False
    # Write output
    if opts.stdout or outfname is None:
        if opts.no_sparse:
            sys.stdout.buffer.write(decomp)
        else:
            sys.stdout.buffer.write(decomp)
    else:
        try:
            if opts.no_sparse:
                with open(outfname, 'wb') as f:
                    f.write(decomp)
            else:
                # Create sparse file for null runs
                with open(outfname, 'wb') as f:
                    i = 0
                    while i < len(decomp):
                        # Find non-null region
                        if decomp[i] == 0:
                            # Find end of null run
                            j = i
                            while j < len(decomp) and decomp[j] == 0:
                                j += 1
                            # Seek instead of writing nulls
                            f.seek(j - i, 1)
                            if j == len(decomp):
                                # At EOF, need to truncate to proper size
                                f.truncate()
                            i = j
                        else:
                            # Find end of non-null run
                            j = i
                            while j < len(decomp) and decomp[j] != 0:
                                j += 1
                            f.write(decomp[i:j])
                            i = j
            try: os.chmod(outfname, stat.S_IMODE(st.st_mode))
            except: pass
            try: os.utime(outfname, (st.st_atime, st.st_mtime))
            except: pass
        except OSError as e:
            msg_error('%s: %s', outfname, e.strerror)
            try: os.unlink(outfname)
            except: pass
            return False
        if not opts.keep:
            try: os.unlink(fname)
            except: pass
    if opts.verbose >= 1:
        show_verbose_info(fname, len(data), len(decomp), False)
    return True

