def main():
    parse_args()

    if opts.info_memory:
        do_info_memory()
        sys.exit(0)

    # Handle version flag
    # (already handled in parse_args)

    # Handle --format=lzip compress
    if opts.format == 'lzip' and opts.mode != 'decompress' and opts.mode != 'test':
        msg_error('Compression of lzip files (.lz) is not supported')
        sys.exit(1)

    # Handle --no-adjust with memlimit
    if opts.no_adjust and opts.memlimit_compress:
        p = opts.preset
        limit_mib = opts.memlimit_compress // (1024*1024)
        ncpu = os.cpu_count() or 1
        nthreads = opts.threads if opts.threads != 0 else ncpu
        comp_mem = get_comp_mem_mib(nthreads)
        if comp_mem > limit_mib:
            msg_error('Memory usage limit is too low for the given filter setup.')
            msg_error('%d MiB of memory is required. The limit is %d MiB.', comp_mem, limit_mib)
            sys.exit(1)

    # Handle raw format warning
    if opts.format == 'raw':
        if opts.verbose >= 0:
            sys.stderr.write('%s: Using a preset in raw mode is discouraged.\n' % PROGRAM_NAME)
            sys.stderr.write('%s: The exact options of the presets may vary between software versions.\n' % PROGRAM_NAME)

    # Determine operation mode
    mode = opts.mode
    if mode is None:
        # Determine from context
        prog = PROGRAM_NAME
        if prog in ('unxz', 'unlzma'):
            mode = 'decompress'
        elif prog in ('xzcat', 'lzcat'):
            mode = 'decompress'
            opts.stdout = True
        else:
            mode = 'compress'

    if mode == 'list':
        if not opts.filenames:
            msg_error('--list does not support reading from standard input')
            sys.exit(1)
        ok = list_files(opts.filenames)
        sys.exit(opts.exit_status)

    # Get filenames
    filenames = opts.filenames if opts.filenames else ['-']

    for fname in filenames:
        if mode == 'compress':
            process_file_compress(fname)
        elif mode == 'decompress':
            process_file_decompress(fname)
        elif mode == 'test':
            process_file_test(fname)

    sys.exit(opts.exit_status)

if __name__ == '__main__':
    main()
