            elif k == 'single-stream': opts.single_stream=True
            elif k == 'no-sparse': opts.no_sparse=True
            elif k == 'suffix':
                s = getv()
                opts.suffix = s if s.startswith('.') else '.'+s
            elif k == 'files':
                opts.files_from = getv() if v is not None else None
                if opts.files_from is None: opts.files_from = '-'
            elif k == 'files0':
