            return buf
    return lzma.decompress(data, format=fmt)

def get_comp_mem_t1():
    p = opts.preset
    return EXTREME_MEM_T1.get(p, 94) if opts.extreme else PRESET_MEM_T1.get(p, 94)

def get_comp_mem(nthreads):
    t1 = get_comp_mem_t1()
    if nthreads <= 1: return t1
    params = (EXTREME_PRESETS if opts.extreme else PRESETS).get(opts.preset, PRESETS[6])
    d_mib = params[0] / (1<<20)
    extra = d_mib * 9 - 0.896
    return int(round(nthreads * (t1 + extra)))

def get_decomp_mem(): return PRESET_DECOMP.get(opts.preset, 9)

def get_filter_str():
    p = opts.preset
    params = (EXTREME_PRESETS if opts.extreme else PRESETS).get(p, PRESETS[6])
    d, mode, mf, nice, depth, lc, lp, pb = params
    ds = '%dMiB' % (d>>20) if d >= (1<<20) else '%dKiB' % (d>>10)
    return '--lzma2=dict=%s,lc=%d,lp=%d,pb=%d,mode=%s,nice=%d,mf=%s,depth=%d' % (
        ds, lc, lp, pb, mode, nice, mf, depth)

def nthreads_effective():
    ncpu = os.cpu_count() or 1
    return opts.threads if opts.threads > 0 else ncpu

def show_vv():
    if opts.verbose < 2: return
    msg_v2(get_filter_str())
    nt = nthreads_effective()
    if opts.threads != 1 and (opts.threads == 0 or opts.threads >= 2):
        msg_v2('Using up to %d threads.', nt)
    cm = get_comp_mem(nt)
    lim = opts.memlimit_compress
    if lim:
        lim_mib = lim >> 20
        msg_v2('%d MiB of memory is required. The limit is %d MiB.', cm, lim_mib)
    else:
        msg_v2('%d MiB of memory is required. The limiter is disabled.', cm)
    msg_v2('Decompression will need %d MiB of memory.', get_decomp_mem())
    if nt > 1 and not lim:
        mt_lim = get_mt_limit_mib()
        per = cm / nt
        max_t = int(mt_lim / per) if per > 0 else nt
        if max_t < nt:
            msg_v2('Reduced the number of threads from %d to %d to not exceed the memory usage limit of %d MiB',
                   nt, max_t, mt_lim)

def show_v(fname, cs, us):
    if opts.verbose < 1: return
    if us == 0: r_str = '---'; sym = '>'
    else:
        r = cs/us
        if r >= 9.9995: r_str = '9.999'; sym = '>'
        else: r_str = '%.3f' % r; sym = '='
    sys.stderr.write('%s: %s / %s %s %s\n' % (fname, format_size(cs), format_size(us), sym, r_str))

def is_tty(f):
    try: return os.isatty(f.fileno())
    except: return False

def do_compress_stream(data, fname_label):
    show_vv()
    try: comp = compress_data(data)
    except Exception as e:
        msg_error('%s: %s', fname_label, str(e)); return None
    show_v(fname_label, len(comp), len(data))
    return comp

def do_decompress_stream(data, fname_label):
    try: decomp = decompress_data(data, opts.single_stream)
    except lzma.LZMAError as e:
        err = str(e).lower()
        if 'check' in err or 'crc' in err or 'integrity' in err:
            msg_error('%s: Compressed data is corrupt', fname_label)
        else:
            msg_error('%s: File format not recognized', fname_label)
        return None
    except: msg_error('%s: File format not recognized', fname_label); return None
    show_v(fname_label, len(data), len(decomp))
    return decomp

def process_stdin_compress():
    if is_tty(sys.stdout) and not opts.force:
        msg_error('Compressed data not written to a terminal')
        return False
    data = sys.stdin.buffer.read()
    comp = do_compress_stream(data, '(stdin)')
    if comp is None: return False
    sys.stdout.buffer.write(comp); return True

def process_stdin_decompress():
    data = sys.stdin.buffer.read()
    decomp = do_decompress_stream(data, '(stdin)')
    if decomp is None: return False
    sys.stdout.buffer.write(decomp); return True

def process_stdin_test():
    data = sys.stdin.buffer.read()
    try: decomp = decompress_data(data, opts.single_stream)
    except: msg_error('(stdin): File format not recognized'); return False
    show_v('(stdin)', len(data), len(decomp)); return True

def copy_meta(src_st, dst_path):
    try: os.chmod(dst_path, stat.S_IMODE(src_st.st_mode))
    except: pass
    try: os.utime(dst_path, (src_st.st_atime, src_st.st_mtime))
    except: pass

def do_compress(fname):
    if fname == '-': return process_stdin_compress()
    try: st = os.stat(fname)
    except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
    if not stat.S_ISREG(st.st_mode) and not stat.S_ISLNK(st.st_mode):
        if not opts.force: msg_warn('%s: Not a regular file, skipping', fname); return False
    suf = get_suffix()
    if not opts.force and fname.endswith(suf):
        msg_warn("%s: File already has '%s' suffix, skipping", fname, suf); return False
    if opts.stdout:
        try:
            with open(fname, 'rb') as f: data = f.read()
        except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
        comp = do_compress_stream(data, fname)
        if comp is None: return False
        sys.stdout.buffer.write(comp); return True
    outfname = fname + suf
    if not opts.force and os.path.exists(outfname):
        msg_error('%s: File exists', outfname); return False
    try:
        with open(fname, 'rb') as f: data = f.read()
    except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
    comp = do_compress_stream(data, fname)
    if comp is None: return False
    try:
        with open(outfname, 'wb') as f: f.write(comp)
        copy_meta(st, outfname)
    except OSError as e:
        msg_error('%s: %s', outfname, e.strerror)
        try: os.unlink(outfname)
        except: pass
        return False
    if not opts.keep:
        try: os.unlink(fname)
        except: pass
    return True

def do_decompress(fname):
    if fname == '-': return process_stdin_decompress()
    try: st = os.stat(fname)
    except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
    if opts.stdout:
        try:
            with open(fname, 'rb') as f: data = f.read()
        except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
        decomp = do_decompress_stream(data, fname)
        if decomp is None: return False
        sys.stdout.buffer.write(decomp); return True
    outfname = decomp_name(fname)
    if outfname is None:
        msg_warn('%s: Unknown suffix, skipping', fname); return False
    if not opts.force and os.path.exists(outfname):
        msg_error('%s: File exists', outfname); return False
    try:
        with open(fname, 'rb') as f: data = f.read()
    except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
    decomp = do_decompress_stream(data, fname)
    if decomp is None: return False
    try:
        if opts.no_sparse:
            with open(outfname, 'wb') as f: f.write(decomp)
        else:
            with open(outfname, 'wb') as f:
                i = 0
                while i < len(decomp):
                    if decomp[i] == 0:
                        j = i
                        while j < len(decomp) and decomp[j] == 0: j += 1
                        f.seek(j-i, 1)
                        if j == len(decomp): f.truncate()
                        i = j
                    else:
                        j = i
                        while j < len(decomp) and decomp[j] != 0: j += 1
                        f.write(decomp[i:j]); i = j
        copy_meta(st, outfname)
    except OSError as e:
        msg_error('%s: %s', outfname, e.strerror)
        try: os.unlink(outfname)
        except: pass
        return False
    if not opts.keep:
        try: os.unlink(fname)
        except: pass
    return True

def do_test(fname):
    if fname == '-': return process_stdin_test()
    try:
        with open(fname, 'rb') as f: data = f.read()
    except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
    try: decomp = decompress_data(data, opts.single_stream)
    except lzma.LZMAError as e:
        err = str(e).lower()
        if 'check' in err or 'crc' in err:
            msg_error('%s: Compressed data is corrupt', fname)
        else: msg_error('%s: File format not recognized', fname)
        return False
    except: msg_error('%s: File format not recognized', fname); return False
    show_v(fname, len(data), len(decomp)); return True

def parse_xz_file(fname):
    try:
        with open(fname, 'rb') as f: data = f.read()
    except OSError as e: return None, e.strerror
    streams, err = parse_xz_data(data)
    if err: return None, err
    # Fix block co to be absolute
    offset = 0
    for s in streams:
        s['abs_start'] = offset
        offset += s['cs'] + s['pad']
    return streams, None

def do_list(filenames):
    if not filenames or '-' in filenames:
        msg_error('--list does not support reading from standard input'); return False
    all_ok = True
    ts=0; tb=0; tc=0; tu=0; tp=0; tf=0; all_cts=set()
    file_infos = []
    for fname in filenames:
        streams, err = parse_xz_file(fname)
        if err: msg_error('%s: %s', fname, err); all_ok=False; continue
        fs=len(streams); fb=sum(len(s['blocks']) for s in streams)
        fc=sum(s['cs'] for s in streams); fu=sum(s['us'] for s in streams)
        fp=sum(s['pad'] for s in streams)
        fcts=set(s['ct'] for s in streams)
        file_infos.append((fname, streams, fs, fb, fc, fu, fp, fcts))
        ts+=fs; tb+=fb; tc+=fc; tu+=fu; tp+=fp; tf+=1; all_cts|=fcts

    nf = len(file_infos)
    if not opts.verbose and not opts.robot:
        print('Strms  Blocks   Compressed Uncompressed  Ratio  Check   Filename')
        for fname, streams, fs, fb, fc, fu, fp, fcts in file_infos:
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            print('%5d  %6d   %10s %12s  %5s  %-8s%s' % (
                fs, fb, format_size(fc), format_size(fu), format_ratio(fc,fu), ct_str, fname))
        if nf > 1:
            print('-'*79)
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(all_cts))
            print('%5d  %6d   %10s %12s  %5s  %-8s%d files' % (
                ts, tb, format_size(tc), format_size(tu),
                format_ratio(tc,tu), ct_str, nf))
    elif opts.robot:
        for fname, streams, fs, fb, fc, fu, fp, fcts in file_infos:
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            print('name\t%s' % fname)
            print('file\t%d\t%d\t%d\t%d\t%s\t%s\t%d' % (
                fs,fb,fc,fu,format_ratio(fc,fu),ct_str,fp))
            if opts.verbose >= 1:
                gblock = 0
                for si, s in enumerate(streams, 1):
                    sco = s.get('abs_start', 0)
                    suo = sum(streams[j]['us'] for j in range(si-1))
                    sct = CHECK_NAMES.get(s['ct'],'?')
                    print('stream\t%d\t%d\t%d\t%d\t%d\t%d\t%s\t%s\t%d' % (
                        si,len(s['blocks']),sco,suo,s['cs'],s['us'],
                        format_ratio(s['cs'],s['us']),sct,s['pad']))
                    for bi, b in enumerate(s['blocks'], 1):
                        gblock += 1
                        bct = CHECK_NAMES.get(b['ct'],'?')
                        bco = b['co'] + sco
                        print('block\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%s\t%s' % (
                            si,bi,gblock,bco,b['uo']+suo,b['ts'],b['us'],
                            format_ratio(b['ts'],b['us']),bct))
        ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(all_cts))
        print('totals\t%d\t%d\t%d\t%d\t%s\t%s\t%d\t%d' % (
            ts,tb,tc,tu,format_ratio(tc,tu),ct_str,tp,nf))
    else:
        # verbose non-robot
        for fi, (fname, streams, fs, fb, fc, fu, fp, fcts) in enumerate(file_infos, 1):
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            print('%s (%d/%d)' % (fname, fi, nf))
            print('  %-19s%d' % ('Streams:', fs))
            print('  %-19s%d' % ('Blocks:', fb))
            print('  %-19s%s' % ('Compressed size:', format_size_vb(fc)))
            print('  %-19s%s' % ('Uncompressed size:', format_size_vb(fu)))
            print('  %-19s%s' % ('Ratio:', format_ratio(fc,fu)))
            print('  %-19s%s' % ('Check:', ct_str))
            print('  %-19s%s' % ('Stream Padding:', format_size_vb(fp)))
            print('  Streams:')
            print('    Stream    Blocks      CompOffset    UncompOffset        CompSize      UncompSize  Ratio  Check      Padding')
            uoff2 = 0
            for si, s in enumerate(streams, 1):
                sco = s.get('abs_start', 0)
                sct = CHECK_NAMES.get(s['ct'],'?')
                print('%10d%10d%16d%16d%16d%16d%7s  %-11s%7d' % (
                    si,len(s['blocks']),sco,uoff2,s['cs'],s['us'],
                    format_ratio(s['cs'],s['us']),sct,s['pad']))
                uoff2 += s['us']
            print('  Blocks:')
            print('    Stream     Block      CompOffset    UncompOffset       TotalSize      UncompSize  Ratio  Check')
            for si, s in enumerate(streams, 1):
                sco = s.get('abs_start', 0)
                suo = sum(streams[j]['us'] for j in range(si-1))
                for bi, b in enumerate(s['blocks'], 1):
                    bct = CHECK_NAMES.get(b['ct'],'?')
                    bco = b['co'] + sco
                    print('%10d%10d%16d%16d%16d%16d%7s  %s' % (
                        si,bi,bco,b['uo']+suo,b['ts'],b['us'],
                        format_ratio(b['ts'],b['us']),bct))
            print()
        if nf > 1:
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(all_cts))
            print('Totals:')
            print('  %-19s%d' % ('Number of files:', nf))
            print('  %-19s%d' % ('Streams:', ts))
            print('  %-19s%d' % ('Blocks:', tb))
            print('  %-19s%s' % ('Compressed size:', format_size_vb(tc)))
            print('  %-19s%s' % ('Uncompressed size:', format_size_vb(tu)))
            print('  %-19s%s' % ('Ratio:', format_ratio(tc,tu)))
            print('  %-19s%s' % ('Check:', ct_str))
            print('  %-19s%s' % ('Stream Padding:', format_size_vb(tp)))
    return all_ok

def parse_size(s):
    s = s.strip()
    if s == '0': return 0
    if s.endswith('%'):
        return int(get_ram_mib() * 1024 * 1024 * float(s[:-1]) / 100)
    mult = 1; num = s
    for suf, val in [('TiB',1<<40),('GiB',1<<30),('MiB',1<<20),('KiB',1<<10),
                     ('TB',10**12),('GB',10**9),('MB',10**6),('KB',10**3),
                     ('T',1<<40),('G',1<<30),('M',1<<20),('K',1<<10)]:
        if s.upper().endswith(suf.upper()):
            num = s[:-len(suf)]; mult = val; break
    try: return int(float(num) * mult)
    except: return 0

