        except: pass
        return False
    if not opts.keep:
        try: os.unlink(fname)
        except: pass
    return True

def do_decompress(fname):
    if fname == '-': return process_stdin_decompress()
    try: st = os.stat(fname)
    except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
    if opts.stdout:
        try:
            with open(fname, 'rb') as f: data = f.read()
        except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
        decomp = do_decompress_stream(data, fname)
        if decomp is None: return False
        sys.stdout.buffer.write(decomp); return True
    outfname = decomp_name(fname)
    if outfname is None:
        msg_warn('%s: Unknown suffix, skipping', fname); return False
    if not opts.force and os.path.exists(outfname):
        msg_error('%s: File exists', outfname); return False
    try:
        with open(fname, 'rb') as f: data = f.read()
    except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
    decomp = do_decompress_stream(data, fname)
    if decomp is None: return False
    try:
        if opts.no_sparse:
            with open(outfname, 'wb') as f: f.write(decomp)
        else:
            with open(outfname, 'wb') as f:
                i = 0
                while i < len(decomp):
                    if decomp[i] == 0:
                        j = i
                        while j < len(decomp) and decomp[j] == 0: j += 1
                        f.seek(j-i, 1)
                        if j == len(decomp): f.truncate()
                        i = j
                    else:
                        j = i
                        while j < len(decomp) and decomp[j] != 0: j += 1
                        f.write(decomp[i:j]); i = j
        copy_meta(st, outfname)
    except OSError as e:
        msg_error('%s: %s', outfname, e.strerror)
        try: os.unlink(outfname)
        except: pass
        return False
    if not opts.keep:
        try: os.unlink(fname)
        except: pass
    return True

def do_test(fname):
    if fname == '-': return process_stdin_test()
    try:
        with open(fname, 'rb') as f: data = f.read()
    except OSError as e: msg_error('%s: %s', fname, e.strerror); return False
    try: decomp = decompress_data(data, opts.single_stream)
    except lzma.LZMAError as e:
        err = str(e).lower()
        if 'check' in err or 'crc' in err:
            msg_error('%s: Compressed data is corrupt', fname)
        else: msg_error('%s: File format not recognized', fname)
        return False
    except: msg_error('%s: File format not recognized', fname); return False
    show_v(fname, len(data), len(decomp)); return True

def parse_xz_file(fname):
    try:
        with open(fname, 'rb') as f: data = f.read()
    except OSError as e: return None, e.strerror
    streams, err = parse_xz_data(data)
    if err: return None, err
    # Fix block co to be absolute
    offset = 0
    for s in streams:
        s['abs_start'] = offset
        offset += s['cs'] + s['pad']
    return streams, None

def do_list(filenames):
    if not filenames or '-' in filenames:
        msg_error('--list does not support reading from standard input'); return False
    all_ok = True
    ts=0; tb=0; tc=0; tu=0; tp=0; tf=0; all_cts=set()
    file_infos = []
    for fname in filenames:
        streams, err = parse_xz_file(fname)
        if err: msg_error('%s: %s', fname, err); all_ok=False; continue
        fs=len(streams); fb=sum(len(s['blocks']) for s in streams)
        fc=sum(s['cs'] for s in streams); fu=sum(s['us'] for s in streams)
        fp=sum(s['pad'] for s in streams)
        fcts=set(s['ct'] for s in streams)
        file_infos.append((fname, streams, fs, fb, fc, fu, fp, fcts))
        ts+=fs; tb+=fb; tc+=fc; tu+=fu; tp+=fp; tf+=1; all_cts|=fcts

    nf = len(file_infos)
    if not opts.verbose and not opts.robot:
        print('Strms  Blocks   Compressed Uncompressed  Ratio  Check   Filename')
        for fname, streams, fs, fb, fc, fu, fp, fcts in file_infos:
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            print('%5d  %6d   %10s %12s  %5s  %-8s%s' % (
                fs, fb, format_size(fc), format_size(fu), format_ratio(fc,fu), ct_str, fname))
        if nf > 1:
            print('-'*79)
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(all_cts))
            print('%5d  %6d   %10s %12s  %5s  %-8s%d files' % (
                ts, tb, format_size(tc), format_size(tu),
                format_ratio(tc,tu), ct_str, nf))
    elif opts.robot:
        for fname, streams, fs, fb, fc, fu, fp, fcts in file_infos:
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            print('name\t%s' % fname)
            print('file\t%d\t%d\t%d\t%d\t%s\t%s\t%d' % (
                fs,fb,fc,fu,format_ratio(fc,fu),ct_str,fp))
            if opts.verbose >= 1:
                gblock = 0
                for si, s in enumerate(streams, 1):
                    sco = s.get('abs_start', 0)
                    suo = sum(streams[j]['us'] for j in range(si-1))
                    sct = CHECK_NAMES.get(s['ct'],'?')
                    print('stream\t%d\t%d\t%d\t%d\t%d\t%d\t%s\t%s\t%d' % (
                        si,len(s['blocks']),sco,suo,s['cs'],s['us'],
                        format_ratio(s['cs'],s['us']),sct,s['pad']))
                    for bi, b in enumerate(s['blocks'], 1):
                        gblock += 1
                        bct = CHECK_NAMES.get(b['ct'],'?')
                        bco = b['co'] + sco
                        print('block\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%s\t%s' % (
                            si,bi,gblock,bco,b['uo']+suo,b['ts'],b['us'],
                            format_ratio(b['ts'],b['us']),bct))
        ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(all_cts))
        print('totals\t%d\t%d\t%d\t%d\t%s\t%s\t%d\t%d' % (
            ts,tb,tc,tu,format_ratio(tc,tu),ct_str,tp,nf))
    else:
        # verbose non-robot
        for fi, (fname, streams, fs, fb, fc, fu, fp, fcts) in enumerate(file_infos, 1):
            ct_str = ','.join(CHECK_NAMES.get(c,'?') for c in sorted(fcts))
            print('%s (%d/%d)' % (fname, fi, nf))
            print('  %-19s%d' % ('Streams:', fs))
            print('  %-19s%d' % ('Blocks:', fb))
            print('  %-19s%s' % ('Compressed size:', format_size_vb(fc)))
            print('  %-19s%s' % ('Uncompressed size:', format_size_vb(fu)))
            print('  %-19s%s' % ('Ratio:', format_ratio(fc,fu)))
            print('  %-19s%s' % ('Check:', ct_str))
            print('  %-19s%s' % ('Stream Padding:', format_size_vb(fp)))
            print('  Streams:')
            print('    Stream    Blocks      CompOffset    UncompOffset        CompSize      UncompSize  Ratio  Check      Padding')
            uoff2 = 0
            for si, s in enumerate(streams, 1):
                sco = s.get('abs_start', 0)
                sct = CHECK_NAMES.get(s['ct'],'?')
                print('%10d%10d%16d%16d%16d%16d%7s  %-11s%7d' % (
                    si,len(s['blocks']),sco,uoff2,s['cs'],s['us'],
                    format_ratio(s['cs'],s['us']),sct,s['pad']))
                uoff2 += s['us']
            print('  Blocks:')
            print('    Stream     Block      CompOffset    UncompOffset       TotalSize      UncompSize  Ratio  Check')
            for si, s in enumerate(streams, 1):
                sco = s.get('abs_start', 0)
                suo = sum(streams[j]['us'] for j in range(si-1))
                for bi, b in enumerate(s['blocks'], 1):
                    bct = CHECK_NAMES.get(b['ct'],'?')
                    bco = b['co'] + sco
                    print('%10d%10d%16d%16d%16d%16d%7s  %s' % (
                        si,bi,bco,b['uo']+suo,b['ts'],b['us'],
