            print('  %-19s%d' % ('Blocks:', tb))
            print('  %-19s%s' % ('Compressed size:', format_size_vb(tc)))
            print('  %-19s%s' % ('Uncompressed size:', format_size_vb(tu)))
            print('  %-19s%s' % ('Ratio:', format_ratio(tc,tu)))
            print('  %-19s%s' % ('Check:', ct_str))
            print('  %-19s%s' % ('Stream Padding:', format_size_vb(tp)))
    return all_ok

def parse_size(s):
    s = s.strip()
    if s == '0': return 0
    if s.endswith('%'):
        return int(get_ram_mib() * 1024 * 1024 * float(s[:-1]) / 100)
    mult = 1; num = s
    for suf, val in [('TiB',1<<40),('GiB',1<<30),('MiB',1<<20),('KiB',1<<10),
                     ('TB',10**12),('GB',10**9),('MB',10**6),('KB',10**3),
                     ('T',1<<40),('G',1<<30),('M',1<<20),('K',1<<10)]:
        if s.upper().endswith(suf.upper()):
            num = s[:-len(suf)]; mult = val; break
    try: return int(float(num) * mult)
    except: return 0

