def parse_args():
    prog = PROGRAM_NAME
    if prog == 'unxz': opts.mode = 'decompress'
    elif prog == 'xzcat': opts.mode = 'decompress'; opts.stdout = True
    elif prog == 'lzma': opts.format = 'lzma'
    elif prog == 'unlzma': opts.mode = 'decompress'; opts.format = 'lzma'
    elif prog == 'lzcat': opts.mode = 'decompress'; opts.stdout = True; opts.format = 'lzma'

    args = sys.argv[1:]; i = 0
    CHECK_MAP = {'none':CHECK_NONE,'crc32':CHECK_CRC32,'crc64':CHECK_CRC64,'sha256':CHECK_SHA256}
    FMT_VALID = ('auto','xz','lzma','lzip','raw')

    def nextarg():
        nonlocal i; i += 1
        if i >= len(args): msg_error('Option requires an argument'); sys.exit(1)
        return args[i]

    while i < len(args):
        a = args[i]
        if a == '--': i += 1; break
        if not a.startswith('-') or a == '-':
            opts.filenames.append(a); i += 1; continue
        if a.startswith('--'):
            lo = a[2:]; eq = lo.find('=')
            k = lo[:eq] if eq >= 0 else lo
            v = lo[eq+1:] if eq >= 0 else None
            def getv(): return v if v is not None else nextarg()
            if k in ('compress','z'): opts.mode='compress'
            elif k in ('decompress','uncompress','d'): opts.mode='decompress'
            elif k in ('test','t'): opts.mode='test'
            elif k in ('list','l'): opts.mode='list'
            elif k in ('keep','k'): opts.keep=True
            elif k in ('force','f'): opts.force=True
            elif k in ('stdout','to-stdout','c'): opts.stdout=True
            elif k == 'no-sync': opts.no_sync=True
            elif k == 'single-stream': opts.single_stream=True
            elif k == 'no-sparse': opts.no_sparse=True
            elif k == 'suffix':
                s = getv()
                opts.suffix = s if s.startswith('.') else '.'+s
            elif k == 'files':
                opts.files_from = getv() if v is not None else None
                if opts.files_from is None: opts.files_from = '-'
            elif k == 'files0':
                opts.files_from = getv() if v is not None else None
                if opts.files_from is None: opts.files_from = '-'
                opts.files_null = True
            elif k == 'format':
                opts.format = getv().lower()
                if opts.format not in FMT_VALID:
                    msg_error('%s: Unknown file format type', opts.format); sys.exit(1)
            elif k == 'check':
                cs = getv().lower()
                if cs not in CHECK_MAP:
                    msg_error('%s: Unknown integrity check type', cs); sys.exit(1)
                opts.check = CHECK_MAP[cs]
            elif k == 'ignore-check': opts.ignore_check=True
            elif k in ('extreme','e'): opts.extreme=True
            elif k == 'threads':
                opts.threads = int(getv())
            elif k == 'block-size': opts.block_size = parse_size(getv())
            elif k in ('memlimit-compress',): opts.memlimit_compress=parse_size(getv())
            elif k == 'memlimit-decompress': opts.memlimit_decompress=parse_size(getv())
            elif k == 'memlimit-mt-decompress': opts.memlimit_mt_decompress=parse_size(getv())
            elif k in ('memlimit','M'):
                val = parse_size(getv())
                opts.memlimit_compress=val; opts.memlimit_decompress=val
                opts.memlimit_mt_decompress=val
            elif k == 'no-adjust': opts.no_adjust=True
            elif k in ('quiet','q'): opts.quiet+=1
            elif k in ('verbose','v'): opts.verbose+=1
            elif k in ('no-warn','Q'): opts.no_warn=True
            elif k == 'robot': opts.robot=True
            elif k == 'info-memory': opts.info_memory=True
            elif k in ('help','h'): show_help(False); sys.exit(0)
            elif k in ('long-help','H'): show_help(True); sys.exit(0)
            elif k in ('version','V'): show_version(); sys.exit(0)
            elif k.startswith(('lzma1','lzma2','x86','arm','powerpc','ia64',
                                'sparc','riscv','delta','filters','block-list',
                                'flush-timeout','armthumb','arm64')): pass
            elif k == 'filters-help': pass
            else:
                msg_error('--%s: Unknown option', k); sys.exit(1)
        else:
            j = 1
            while j < len(a):
                c = a[j]
                if c in '0123456789': opts.preset = int(c)
                elif c == 'z': opts.mode='compress'
                elif c == 'd': opts.mode='decompress'
                elif c == 't': opts.mode='test'
                elif c == 'l': opts.mode='list'
                elif c == 'k': opts.keep=True
                elif c == 'f': opts.force=True
                elif c == 'c': opts.stdout=True
                elif c == 'e': opts.extreme=True
                elif c == 'q': opts.quiet+=1
                elif c == 'v': opts.verbose+=1
                elif c == 'Q': opts.no_warn=True
                elif c == 'T':
                    rest = a[j+1:]
                    opts.threads = int(rest if rest else nextarg()); j=len(a)-1
                elif c == 'S':
                    rest = a[j+1:]
                    s = rest if rest else nextarg()
                    opts.suffix = s if s.startswith('.') else '.'+s; j=len(a)-1
                elif c == 'M':
                    rest = a[j+1:]
                    val = parse_size(rest if rest else nextarg()); j=len(a)-1
                    opts.memlimit_compress=val
                elif c == 'F':
                    rest = a[j+1:]
                    opts.format = (rest if rest else nextarg()).lower(); j=len(a)-1
                    if opts.format not in FMT_VALID:
                        msg_error('%s: Unknown file format type', opts.format); sys.exit(1)
                elif c == 'C':
                    rest = a[j+1:]
                    cs = (rest if rest else nextarg()).lower(); j=len(a)-1
                    if cs not in CHECK_MAP:
                        msg_error('%s: Unknown integrity check type', cs); sys.exit(1)
                    opts.check = CHECK_MAP[cs]
                elif c == 'h': show_help(False); sys.exit(0)
                elif c == 'H': show_help(True); sys.exit(0)
                elif c == 'V': show_version(); sys.exit(0)
                else: msg_error('-%s: Unknown option', c); sys.exit(1)
                j += 1
        i += 1
    opts.filenames.extend(args[i:])

    if opts.files_from:
        src = sys.stdin.buffer if opts.files_from == '-' else open(opts.files_from, 'rb')
        content = src.read()
        if opts.files_from != '-': src.close()
        sep = b'\x00' if opts.files_null else b'\n'
        for fn in content.split(sep):
            fn = fn.decode(errors='replace').rstrip('\r')
            if fn: opts.filenames.append(fn)

def main():
    parse_args()

    if opts.info_memory:
        do_info_memory(); sys.exit(0)

    # Check for lzip compression
