# The original executable is owned by root with execute-only permissions
# I need to copy it to a temp location and then replace it
# Let me use a different approach: write a C wrapper that calls the Python script

# Actually, the simplest approach is to create a proper Python script
# with the correct shebang line and make it executable, 
# and then in compile.sh we can remove/replace the executable

# Let me check if we can remove it
ls -la
# Try to create a new file named 'executable' after removing the old one
# Actually, we need a C compiled binary to match the "executable" name

# Let me compile a C wrapper
cat > xz_main.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <libgen.h>

int main(int argc, char *argv[]) {
    char *dir = dirname(argv[0]);
    char *script = malloc(strlen(dir) + 20);
    sprintf(script, "%s/xz_tool.py", dir);

    char **new_argv = malloc((argc + 2) * sizeof(char*));
    new_argv[0] = "python3";
    new_argv[1] = script;
    for (int i = 1; i < argc; i++) {
        new_argv[i+1] = argv[i];
    }
    new_argv[argc+1] = NULL;

    // Set PYTHONPATH to find the script
    execvp("python3", new_argv);
    perror("execvp");
    return 1;
}
EOF

gcc -o /tmp/xz_wrapper xz_main.c && echo "C wrapper compiled"
echo "test" | /tmp/xz_wrapper -c > /tmp/wrap_test.xz && echo "Wrapper works"
./executable -dc /tmp/wrap_test.xz && echo "Orig decompresses wrapper output"

